        public void CreateJustOT(IWebFreightContext context)
        {
            CommonDataDomainService commonDomain = new CommonDataDomainService();
            ObjectContext = context;//WebFreightContext.GetContext(0);
            ScreenFieldsRepository = new ScreenFieldsRepository(ObjectContext);
            ScreensRepository = new ScreensRepository(ObjectContext);
            ObjectTable DocumentsFilingObject = ObjectContext.ObjectTables.Where(d => d.Name == "DocumentsFiling" && d.Tenant == 0).FirstOrDefault();
            Dictionary<string, Screen> tenantScreens = ScreensRepository.GetScreensByTenant(0).Where(a => a.ObjectTableId == DocumentsFilingObject.Id).GroupBy(d => d.Code + d.ObjectTableId).ToDictionary(g => g.Key, a => a.FirstOrDefault());
            Dictionary<string, ScreenField> tenantScreenField = new Dictionary<string, ScreenField>();//ScreenFieldsRepository.GetScreenFieldsByTenant(0).Where(a => a.ObjectTableId == DocumentsFilingObject.Id).ToDictionary(d => d.ScreenId + d.ObjectFieldId);

            BuildDocumentsFilingScreens(tenantScreens, tenantScreenField);          
        }

        public void LoadObjectTablesToTenantZero(IWebFreightContext context)
        {
            InitializeService(context);
            Dictionary<string, ObjectTable> objectTables = ObjectTableRepository.GetObjectsByTenant(0).GroupBy(d => d.Name).ToDictionary(g => g.Key, a => a.FirstOrDefault());
            textCodes = new Dictionary<string, TextCode>();
            textCodes = TextCodeRepository.GetTextCodesByTenant(0).GroupBy(d => d.Code + d.Tenant.ToString() + d.ObjectTableId).ToDictionary(d => d.Key, a => a.FirstOrDefault(), StringComparer.OrdinalIgnoreCase);

            CreateAllObjectsTables(objectTables, textCodes);
        }

        private void InitializeService(IWebFreightContext context)
        {
            CommonDataDomainService commonDomain = new CommonDataDomainService();
            ObjectContext = context;//WebFreightContext.GetContext(0);
            TextCodeRepository = new TextCodeRepository(ObjectContext);
            ObjectTableRepository = new ObjectTableRepository(ObjectContext);
            ObjectFieldsRepository = new ObjectFieldRepository(ObjectContext);
            TipRepository = new TipRepository(ObjectContext);
            CounterDefinitionRepository = new CounterDefinitionRepository(ObjectContext);
            MenuButtonRepository = new MenuButtonRepository(ObjectContext);
            MenuButtonGroupRepository = new MenuButtonGroupRepository(ObjectContext);
            TenantSettingRepository = new TenantSettingRepository(ObjectContext);

        }
        bool isUpdate = false;
        Dictionary<string, TextCode> textCodes = null;
        public void LoadObjectsTenantZero(IWebFreightContext context, bool updateMetadatafields = true,int tenant=0)
        {
            InitializeService(context);

            Dictionary<string, ObjectTable> objectTables = ObjectTableRepository.GetObjectsByTenant(0).GroupBy(d => d.Name).ToDictionary(g => g.Key, a => a.FirstOrDefault());
            Dictionary<string, Tip> tips = TipRepository.GetTips(0).GroupBy(d => d.Code).ToDictionary(g => g.Key, a => a.FirstOrDefault());
            if (textCodes == null)
            {
                if (true)
                {
                    textCodes = new Dictionary<string, TextCode>();
                    TextCodeRepository.GetTextCodesByTenant(0).ToList().ForEach(d =>
                    {
                        textCodes.Add(d.Code + d.Tenant.ToString() + d.ObjectTableId, d);
                    });
                }
                else
                {
                    textCodes = TextCodeRepository.GetTextCodesByTenant(0).ToDictionary(d => d.Code + d.Tenant.ToString() + d.ObjectTableId, a => a);
                }
            }

            if (updateMetadatafields)
            {
            }

            if (!isUpdate)
            {
            }

            CreateTableCounters();
            CreateShipmentDeliveryCounters();
            CreateAllTablesTips(tips, textCodes);

            if (updateMetadatafields)
            {               
            
                LoadRolesAndFeatures(tenant);
                CreateMenuButtonsForTenant(tenant);

            }

        
            this.ObjectContext.SaveChanges();
        }

        public void UpdateShipmentLogboxAuomationObjectFields(IWebFreightContext context)
        {

              ObjectTableRepository objectTableRepository = new ObjectTableRepository(0);
              string objectTableid =  objectTableRepository.GetObjectTableIdByName("Shipment");


                List<string> fieldsName = new List<string> { "OwnerLink", "IsDigitalSignRequired", "IsRequestedDocuments" , "IsDepositionRequired", "IsImporterApprovalRequired" };
                ObjectFieldsRepository = new ObjectFieldRepository(context);
                List<ObjectField> objectFields = ObjectFieldsRepository.GetObjectFieldsByFieldsNamesAndObjectTable(fieldsName, objectTableid).ToList();
                if (objectFields.Count > 0)
                {
                    foreach (ObjectField objectField in objectFields)
                    {
                        if (objectField.FieldName == "OwnerLink") objectField.DisplayInEntityVariables = true;
                        else objectField.AllowedinAutomationConditions = true;
                        ObjectFieldsRepository.Update(objectField);
                    }
                    ObjectFieldsRepository.SubmitChanges();
                }
            

        }

        void CreateAllTablesTips(Dictionary<string, Tip> tips, Dictionary<string, TextCode> textCodes)
        {
            List<ObjectTable> tenantObjectTables = ObjectTableRepository.GetObjectsByTenant(0).ToList();
            ObjectTable AirlinesObject = tenantObjectTables.Where(o => o.Name == "Airline").FirstOrDefault();
            ObjectTable PortsObject = tenantObjectTables.Where(o => o.Name == "Port").FirstOrDefault();
            ObjectTable ShippingLinesObject = tenantObjectTables.Where(o => o.Name == "ShippingLine").FirstOrDefault();
            ObjectTable ShipmentObject = tenantObjectTables.Where(o => o.Name == "Shipment").FirstOrDefault();
            ObjectTable CustomerTenantAccessCardObject = tenantObjectTables.Where(o => o.Name == "CustomerTenantAccessCard").FirstOrDefault();
            ObjectTable BIReportObject = tenantObjectTables.Where(o => o.Name == "BIReport").FirstOrDefault();
            Tip airlineTip = AddTips.AddTip(new TipDetails()
            {
                Code = "AIRT",
                Tenant = 0,
                ShortTextCodeDefaultText = " - Airlines are listed  in this pane(%L) - To add a new Airline to your company press the 'new' button(%L)- To import an Airline to your company press the 'add' button(%L)",
                ObjectTableId = AirlinesObject.Id,
                VisibilityDefaultValue = true,
                ShortTextCode = "Airline.Tip.General",
                ShortTextCodeCode = "Airline.Tip.General",
            }, TipRepository, TextCodeRepository, tips, textCodes); ;
            AirlinesObject.MainTipCode = airlineTip.Code;

            Tip portTip = AddTips.AddTip(new TipDetails()
            {
                Code = "PORT",
                Tenant = 0,
                ShortTextCodeDefaultText = " - Ports are listed  in this pane(%L) - To add a Port to your company press the 'add' button(%L)",
                ObjectTableId = PortsObject.Id,
                VisibilityDefaultValue = true,
                ShortTextCode = "Port.Tip.General",
                ShortTextCodeCode = "Port.Tip.General",
            }, TipRepository, TextCodeRepository, tips, textCodes);
            PortsObject.MainTipCode = portTip.Code;

            Tip shippingLineTip = AddTips.AddTip(new TipDetails()
            {
                Code = "SPLT",
                Tenant = 0,
                ShortTextCodeDefaultText = " - Shipping lines are listed  in this pane(%L) - To add a new shipping line to your company press the 'new' button(%L)- To import a shipping line to your company press the 'add' button(%L)  ",
                ObjectTableId = ShippingLinesObject.Id,
                VisibilityDefaultValue = true,
                ShortTextCode = "ShippingLine.Tip.General",
                ShortTextCodeCode = "ShippingLine.Tip.General",
            }, TipRepository, TextCodeRepository, tips, textCodes);
            ShippingLinesObject.MainTipCode = shippingLineTip.Code;

            Tip orderDetailsTip = AddTips.AddTip(new TipDetails()
            {
                Code = "ORDT",
                Tenant = 0,
                ShortTextCodeDefaultText = " These are the ordered quantities and dimensions. The actual package details are managed via the Packages tab.",
                ObjectTableId = ShipmentObject.Id,
                VisibilityDefaultValue = true,
                ShortTextCode = "Shipment.Tip.OrderDetails",
                ShortTextCodeCode = "Shipment.Tip.OrderDetails",
            }, TipRepository, TextCodeRepository, tips, textCodes);

            Tip CustomerTenantAccessCardTip = AddTips.AddTip(new TipDetails()
            {
                Code = "NCDT",
                Tenant = 0,
                ShortTextCodeDefaultText = " Press \"+\" button to connect a customer to that request.",
                ObjectTableId = CustomerTenantAccessCardObject.Id,
                VisibilityDefaultValue = true,
                ShortTextCode = "CustomerTenantAccessCard.Tip.NewCardTip",
                ShortTextCodeCode = "CustomerTenantAccessCard.Tip.NewCardTip",
            }, TipRepository, TextCodeRepository, tips, textCodes);

            Tip BIReportTip = AddTips.AddTip(new TipDetails()
            {
                Code = "BIRE",
                Tenant = 0,
                ShortTextCodeDefaultText = "You can create a new BI report or add from the reports we added for you by clicking on Upload a Standard BI Report button.",
                ObjectTableId = BIReportObject.Id,
                VisibilityDefaultValue = true,
                ShortTextCode = "BIReport.Tip.BITip",
                ShortTextCodeCode = "BIReport.Tip.BITip",
            }, TipRepository, TextCodeRepository, tips, textCodes);

            this.ObjectContext.SaveChanges();
        }

