            AddTextCodes.AddTextCode(new TextCodeDetails() { Code = "Tenant.O.PrepaidCollect", DefaultText = "Prepaid | Collect", ObjectTableId = objectTableId, Tenant = 0, TextCodeTypeCode = "O", }, TextCodeRepository, textcodes);
