            AddTextCodes.AddTextCode(new TextCodeDetails() { Code = "Distributor.M.DistributorHasNoValue", DefaultText = "Please choose a distributor since the user marked as distributor.", ObjectTableId = objectTableId, Tenant = 0, TextCodeTypeCode = "M", }, TextCodeRepository, textcodes);
            ObjectContext.SaveChanges();
        }
