        #region check for new queries

        public IQueryable<QueryPM> CheckForNewQueries(int tenant, string userId)
        {

            List<Query> QueriesList = QueriesRepository.GetQueriesByTenant(tenant).ToList();
            List<QueryColumn> QueryColumnsList = QueryColumnsRepository.GetQueryColumnsByTenant(tenant).ToList();
            List<AdvancedQueryFilter> AdvancedFiltersList = AdvancedQueryFiltersRepository.GetAdvancedQueryFiltersByTenant(tenant).ToList();


            List<Query> SystemQueries = QueriesList.Where(d => d.SystemLevel == true && d.UserId == null).ToList(); //QueriesRepository.GetQueriesByTenantSystemLevel(tenant).ToList();
            List<Query> TenantQueries = QueriesList.Where(d => d.TenantLevel == true && d.UserId == null).ToList(); //QueriesRepository.GetQueriesByTenantTenantLevel(tenant).ToList();
            List<Query> UsersQueries = QueriesList.Where(d => d.UserId == userId).ToList();//QueriesRepository.GetQueryByTenantAndUser(tenant, userId).ToList();

            UserRepository userRep = new UserRepository(tenant);
            bool DoSubmittChanges = false;
            User user = userRep.GetSingleUser(userId, tenant, false);
            if (user != null)
            {
                //----if no queries for user.
                if (UsersQueries.Count() == 0)
                {
                    DoSubmittChanges = true;
                    foreach (Query query in SystemQueries)
                    {
                        List<QueryColumn> queryColumns = QueryColumnsList.Where(d => d.QueryId == query.Id && d.Tenant == tenant).ToList();//QueryColumnsRepository.GetQueryColumnsByQueryTenantOnly(tenant, query.Id).ToList();
                        List<AdvancedQueryFilter> advancedFilters = AdvancedFiltersList.Where(d => d.QueryId == query.Id && d.Tenant == tenant).ToList();//AdvancedQueryFiltersRepository.GetAdvancedQueryFiltersByTenantAndQuery(tenant, query.Id).ToList();

                        Query newQuery = new Query()
                        {
                            Tenant = tenant,
                            UserId = userId,
                            OriginalQueryId = query.Id,
                            Id = IdCounter.GetNumber("Query", tenant).ToString(),
                            ObjectTableId = query.ObjectTableId,
                            QuerySection = query.QuerySection,
                            Code = query.Code,
                            SystemLevel = query.SystemLevel,
                            TenantLevel = query.TenantLevel,
                            IndexOrder = query.IndexOrder,
                            DisplayCount = query.DisplayCount,
                            QueryGroupCode = query.QueryGroupCode,
                            IsAddNewEntityEnabled = query.IsAddNewEntityEnabled,
                            DefaultSortColumn = query.DefaultSortColumn,
                            DefaultSortDirection = query.DefaultSortDirection,
                            NameTextCodeId = query.NameTextCodeId,
                            SpotlightDataTemplate = query.SpotlightDataTemplate,
                        };
                        QueriesRepository.Add(newQuery);

                        foreach (QueryColumn column in queryColumns)
                        {
                            QueryColumn newColumn = new QueryColumn()
                            {
                                ColumnWidth = column.ColumnWidth,
                                Id = IdCounter.GetNumber("QueryColumn", tenant).ToString(),
                                IndexOrder = column.IndexOrder,
                                ObjectFieldId = column.ObjectFieldId,
                                QueryId = newQuery.Id,
                                Tenant = tenant,


                            };
                            QueryColumnsRepository.Add(newColumn);
                        }

                        foreach (AdvancedQueryFilter filter in advancedFilters)
                        {
                            AdvancedQueryFilter newFilter = new AdvancedQueryFilter()
                            {
                                QueryId = newQuery.Id,
                                Id = IdCounter.GetNumber("AdvancedQueryFilter", tenant).ToString(),
                                Tenant = tenant,
                                PredefinedValue = filter.PredefinedValue,
                                ObjectFieldId = filter.ObjectFieldId,
                                IsPredefined = filter.IsPredefined,

                            };
                            AdvancedQueryFiltersRepository.Add(newFilter);
                        }




                    }
                }
                //--------------if there is queries for the user.
                else
                {
                    //------check for system queries.
                    bool notExistsInSystem = true;
                    foreach (Query sysQuery in SystemQueries)
                    {
                        notExistsInSystem = true;
                        foreach (Query query in UsersQueries)
                        {
                            if (query.OriginalQueryId == sysQuery.Id)
                            {
                                notExistsInSystem = false;
                                break;
                            }
                        }

                        if (notExistsInSystem)
                        {
                            DoSubmittChanges = true;
                            List<QueryColumn> queryColumns = QueryColumnsList.Where(d => d.QueryId == sysQuery.Id && d.Tenant == tenant).ToList();//QueryColumnsRepository.GetQueryColumnsByQueryTenantOnly(tenant, sysQuery.Id).ToList();
                            List<AdvancedQueryFilter> advancedFilters = AdvancedFiltersList.Where(d => d.QueryId == sysQuery.Id && d.Tenant == tenant).ToList(); //AdvancedQueryFiltersRepository.GetAdvancedQueryFiltersByTenantAndQuery(tenant, sysQuery.Id).ToList();

                            Query newQuery = new Query()
                            {
                                Tenant = tenant,
                                UserId = userId,
                                OriginalQueryId = sysQuery.Id,
                                Id = IdCounter.GetNumber("Query", tenant).ToString(),
                                ObjectTableId = sysQuery.ObjectTableId,
                                QuerySection = sysQuery.QuerySection,
                                Code = sysQuery.Code,
                                DisplayCount = sysQuery.DisplayCount,
                                QueryGroupCode = sysQuery.QueryGroupCode,
                                IsAddNewEntityEnabled = sysQuery.IsAddNewEntityEnabled,
                                NameTextCodeId = sysQuery.NameTextCodeId,
                                IndexOrder = sysQuery.IndexOrder,
                                SystemLevel = sysQuery.SystemLevel,
                                DefaultSortColumn = sysQuery.DefaultSortColumn,
                                DefaultSortDirection = sysQuery.DefaultSortDirection,
                                TenantLevel = sysQuery.TenantLevel,
                                SpotlightDataTemplate = sysQuery.SpotlightDataTemplate,


                            };

                            QueriesRepository.Add(newQuery);

                            foreach (QueryColumn column in queryColumns)
                            {
                                QueryColumn newColumn = new QueryColumn()
                                {
                                    ColumnWidth = column.ColumnWidth,
                                    Id = IdCounter.GetNumber("QueryColumn", tenant).ToString(),
                                    IndexOrder = column.IndexOrder,
                                    ObjectFieldId = column.ObjectFieldId,
                                    QueryId = newQuery.Id,
                                    Tenant = tenant,

                                };
                                QueryColumnsRepository.Add(newColumn);
                            }

                            foreach (AdvancedQueryFilter filter in advancedFilters)
                            {
                                AdvancedQueryFilter newFilter = new AdvancedQueryFilter()
                                {
                                    QueryId = newQuery.Id,
                                    Id = IdCounter.GetNumber("AdvancedQueryFilter", tenant).ToString(),
                                    Tenant = tenant,
                                    PredefinedValue = filter.PredefinedValue,
                                    ObjectFieldId = filter.ObjectFieldId,
                                    IsPredefined = filter.IsPredefined,

                                };
                                AdvancedQueryFiltersRepository.Add(newFilter);
                            }


                        }

                    }
                    //------ check for tenant queries.


                    bool notExistInTenant = true;
                    foreach (Query tenantQuery in TenantQueries)
                    {
                        notExistInTenant = true;
                        foreach (Query query in UsersQueries)
                        {
                            if (query.OriginalQueryId == tenantQuery.Id)
                            {
                                notExistInTenant = false;
                                break;
                            }
                        }

                        if (notExistInTenant)
                        {
                            DoSubmittChanges = true;
                            List<QueryColumn> queryColumns = QueryColumnsList.Where(d => d.QueryId == tenantQuery.Id && d.Tenant == tenant).ToList();//QueryColumnsRepository.GetQueryColumnsByQueryTenantOnly(tenant, tenantQuery.Id).ToList();
                            List<AdvancedQueryFilter> advancedFilters = AdvancedFiltersList.Where(d => d.QueryId == tenantQuery.Id && d.Tenant == tenant).ToList();//AdvancedQueryFiltersRepository.GetAdvancedQueryFiltersByTenantAndQuery(tenant, tenantQuery.Id).ToList();

                            Query newQuery = new Query()
                            {
                                Tenant = tenant,
                                UserId = userId,
                                OriginalQueryId = tenantQuery.Id,
                                Id = IdCounter.GetNumber("Query", tenant).ToString(),
                                ObjectTableId = tenantQuery.ObjectTableId,
                                QuerySection = tenantQuery.QuerySection,
                                Code = tenantQuery.Code,
                                SystemLevel = tenantQuery.SystemLevel,
                                TenantLevel = tenantQuery.TenantLevel,
                                IndexOrder = tenantQuery.IndexOrder,
                                DisplayCount = tenantQuery.DisplayCount,
                                QueryGroupCode = tenantQuery.QueryGroupCode,
                                IsAddNewEntityEnabled = tenantQuery.IsAddNewEntityEnabled,
                                NameTextCodeId = tenantQuery.NameTextCodeId,
                                DefaultSortDirection = tenantQuery.DefaultSortDirection,
                                DefaultSortColumn = tenantQuery.DefaultSortColumn,
                                SpotlightDataTemplate = tenantQuery.SpotlightDataTemplate,
                            };
                            QueriesRepository.Add(newQuery);

                            foreach (QueryColumn column in queryColumns)
                            {
                                QueryColumn newColumn = new QueryColumn()
                                {
                                    ColumnWidth = column.ColumnWidth,
                                    Id = IdCounter.GetNumber("QueryColumn", tenant).ToString(),
                                    IndexOrder = column.IndexOrder,
                                    ObjectFieldId = column.ObjectFieldId,
                                    QueryId = newQuery.Id,
                                    Tenant = tenant,



                                };
                                QueryColumnsRepository.Add(newColumn);
                            }

                            foreach (AdvancedQueryFilter filter in advancedFilters)
                            {
                                AdvancedQueryFilter newFilter = new AdvancedQueryFilter()
                                {
                                    QueryId = newQuery.Id,
                                    Id = IdCounter.GetNumber("AdvancedQueryFilter", tenant).ToString(),
                                    Tenant = tenant,
                                    PredefinedValue = filter.PredefinedValue,
                                    ObjectFieldId = filter.ObjectFieldId,
                                    IsPredefined = filter.IsPredefined,


                                };
                                AdvancedQueryFiltersRepository.Add(newFilter);
                            }




                        }

                    }

                }
                if (DoSubmittChanges)
                {
                    QueriesRepository.SubmitChanges();
                    QueryColumnsRepository.SubmitChanges();
                    AdvancedQueryFiltersRepository.SubmitChanges();
                }


            }

            QueryQuery queryQuery = new QueryQuery(QueriesRepository);
            IQueryable<QueryPM> FinalUsersQuery = queryQuery.GetQueryByTenantAndUser(tenant, userId);
            return FinalUsersQuery;
        }
